changeSet.sql:
-- 2. Partial unique index: Exactly 1 active default workspace per tenant
CREATE UNIQUE INDEX IF NOT EXISTS uk_tenant_default_workspace
ON UNIPOST_WORKSPACES (tenant_id)
WHERE is_default = TRUE AND "deletedDate" IS NULL;

-- 3. Unique workspace code per tenant
CREATE UNIQUE INDEX IF NOT EXISTS uk_tenant_workspace_code
ON UNIPOST_WORKSPACES (tenant_id, code)
WHERE "deletedDate" IS NULL;

-- 4. Enable Row-Level Security (RLS) on Workspaces
ALTER TABLE UNIPOST_WORKSPACES ENABLE ROW LEVEL SECURITY;

-- 5. Strict Tenant Isolation Policy with Sovereign SYSTEM Root Custody
DROP POLICY IF EXISTS tenant_isolation_workspaces ON UNIPOST_WORKSPACES;
CREATE POLICY tenant_isolation_workspaces ON UNIPOST_WORKSPACES
    FOR ALL
    USING (
        current_setting('app.current_tenant_id', true) = 'SYSTEM'
        OR tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
        OR tenant_id = 'SYSTEM'
    )
    WITH CHECK (
        current_setting('app.current_tenant_id', true) = 'SYSTEM'
        OR (
            tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
            AND tenant_id != 'SYSTEM'
        )
    );
